using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Options with the default reflection-based resolver ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"  Serialized: {json}");

Person? roundTripped = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"  Deserialized: {roundTripped}");

// 2. TryGetTypeInfo<T>() — probe without throwing
//    With the default resolver every type is resolvable, so Person succeeds:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? probed))
    Console.WriteLine($"\nTryGetTypeInfo<Person>  → found ({probed!.Type.Name})");
else
    Console.WriteLine("\nTryGetTypeInfo<Person>  → not found");

// Now use a source-gen context that only knows about Person.
// Asking for Order will return false instead of throwing.
var limited = new JsonSerializerOptions { TypeInfoResolver = AppJsonContext.Default };

if (limited.TryGetTypeInfo<Order>(out JsonTypeInfo<Order>? orderInfo))
    Console.WriteLine($"TryGetTypeInfo<Order>  → found ({orderInfo!.Type.Name})");
else
    Console.WriteLine($"TryGetTypeInfo<Order>  → not found (resolver doesn't know Order)");

// Confirm Person IS resolvable via the same limited context
if (limited.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? personInfo2))
    Console.WriteLine($"TryGetTypeInfo<Person> → found ({personInfo2!.Type.Name})");


// ----- Types & source-gen context -----

public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

[JsonSerializable(typeof(Person))]          // only Person is registered
public partial class AppJsonContext : JsonSerializerContext;

